   comment */

if score >= 90 {
    println("Grade: A")
} or score >= 80 {
    println("Grade: B")
} otherwise {
    println("Grade: F")
}

when day {
    is 1, 2, 3, 4, 5 { println("Weekday") }
    is 6, 7 { println("Weekend!") }
    default { println("Invalid day") }
}

for i in range(1, 6) {
    println("${i}")
}

for_each i, fruit in fruits {
    println("${i}: ${fruit}")
}

mut n int = 5
as_long_as n > 0 {
    println("${n}")
    n--
}

loop {
    mut x string = input()
    if x == "quit" { break }
}

do add(a int, b int) -> int {
    return a + b
}

do greet(name string = "World") -> string {
    return "Hello, ${name}!"
}

do swap(a int, b int) -> (x int, y int) {
    x = b; y = a
    return x, y
}

mut numbers [int] = {1, 2, 3, 4, 5}
numbers[0] = 100
println(len(numbers))

const Person struct { name string; age int }
mut alice Person = Person{ name: "Alice", age: 30 }
alice.age = 31

const Color enum { RED; GREEN; BLUE }
mut myColor Color = Color.RED
if myColor == Color.RED { println("red") }

do parse_int(s string) -> (int, Error) {
    if s == "" { return 0, error("empty string") }
    return 42, nil
}

mut val, err = parse_int("bad")
if err != nil {
    println("Error: ${err}")
    return
}

do wrapper() -> (int, Error) {
    mut val int = might_fail(true) or_return
    return val, nil
}

